// Simple Canvas Meteor Dodge game
// The HTML contains <canvas id="game"></canvas>

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return; // safety
  const ctx = canvas.getContext('2d');

  // Set canvas size (fallback if not set in HTML)
  canvas.width = canvas.clientWidth || 800;
  canvas.height = canvas.clientHeight || 600;

  const ship = {
    w: 40,
    h: 20,
    x: canvas.width / 2 - 20,
    y: canvas.height - 30,
    speed: 5,
  };

  const keys = { ArrowLeft: false, ArrowRight: false };
  window.addEventListener('keydown', (e) => {
    if (e.key in keys) keys[e.key] = true;
  });
  window.addEventListener('keyup', (e) => {
    if (e.key in keys) keys[e.key] = false;
  });

  let meteors = [];
  let spawnTimer = 0;
  const spawnInterval = 1000; // ms
  let lastTime = 0;
  let score = 0;
  let hits = 0;
  const maxHits = 3;

  function spawnMeteor() {
    const radius = 15 + Math.random() * 10;
    const x = Math.random() * (canvas.width - radius * 2) + radius;
    const speed = 1 + score * 0.02; // accelerate with score
    meteors.push({ x, y: -radius, r: radius, speed });
  }

  function update(dt) {
    // Ship movement
    if (keys.ArrowLeft) ship.x -= ship.speed;
    if (keys.ArrowRight) ship.x += ship.speed;
    // Keep within bounds
    ship.x = Math.max(0, Math.min(canvas.width - ship.w, ship.x));

    // Meteors
    spawnTimer += dt;
    if (spawnTimer > spawnInterval) {
      spawnTimer = 0;
      spawnMeteor();
    }
    for (let i = meteors.length - 1; i >= 0; i--) {
      const m = meteors[i];
      m.y += m.speed;
      // collision detection (simple rect-circle)
      const shipRect = { x: ship.x, y: ship.y, w: ship.w, h: ship.h };
      const dx = Math.max(shipRect.x - m.x, 0, m.x - (shipRect.x + shipRect.w));
      const dy = Math.max(shipRect.y - m.y, 0, m.y - (shipRect.y + shipRect.h));
      if (dx * dx + dy * dy < m.r * m.r) {
        hits++;
        meteors.splice(i, 1);
        continue;
      }
      // Remove off-screen
      if (m.y - m.r > canvas.height) {
        meteors.splice(i, 1);
        score++;
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // Ship
    ctx.fillStyle = '#0af';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // Meteors
    ctx.fillStyle = '#a33';
    meteors.forEach((m) => {
      ctx.beginPath();
      ctx.arc(m.x, m.y, m.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // UI
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`Hits: ${hits}/${maxHits}`, 10, 40);
    if (hits >= maxHits) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
  }

  function loop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    if (hits < maxHits) update(dt);
    draw();
    requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);
})();
